form.script:
document.addEventListener('DOMContentLoaded', function () {
    // Bind to this page's CIF company form specifically (do not rely on `.s_website_form`)
    const form = document.getElementById('cif_company_form') || document.querySelector('form[action="/cif/submit/company/cif.form"]') || document.querySelector('form[action="/cif/submit/change"]');
    if (form) {
        form.addEventListener('submit', function (event) {
            const dobInput = document.getElementById('date_of_birth');
            if (dobInput && dobInput.value) {
                const selectedDate = new Date(dobInput.value);
                const today = new Date();
                // Set hours to 0 to compare dates only
                today.setHours(0, 0, 0, 0);

                if (selectedDate > today) {
                    alert("Date of Birth cannot be in the future. Please select a valid date.");
                    // Prevent the form from submitting
                    event.preventDefault();
                    event.stopPropagation();
                }
            }
        });
    }

    // Check verification status on page load
    checkVerificationStatus();
});

// Get the access token from the form
function getAccessToken() {
    const tokenInput = document.querySelector('input[name="cif_token"]') || document.querySelector('input[name="change_token"]');
    return tokenInput ? tokenInput.value : null;
}

