// Reset verification when email changes (ACTIVE)
document.addEventListener('DOMContentLoaded', function() {
    ['email', 'email_address'].forEach(fieldType => {
        const input = document.getElementById(fieldType);
        if (input) {
            input.addEventListener('input', function() {
                const verifyBtn = document.getElementById('btn_verify_' + fieldType);
                if (verifyBtn) {
                    verifyBtn.style.display = 'inline-block';
                    verifyBtn.disabled = false;
                    verifyBtn.textContent = 'Verify';
                }
                const otpSec = document.getElementById(fieldType + '_otp_section');
                if (otpSec) otpSec.style.display = 'none';
                const verified = document.getElementById(fieldType + '_verified');
                if (verified) verified.style.display = 'none';
            });
        }
    });
});

// Email OTP Functions (ACTIVE)
function sendEmailOTP(fieldType) {
    const emailInput = document.getElementById(fieldType);
    const emailAddress = emailInput.value.trim();
    const token = getAccessToken();

    if (!emailAddress) {
        showEmailError(fieldType, 'Please enter an email address first.');
        return;
    }
    if (!isValidEmail(emailAddress)) {
        showEmailError(fieldType, 'Please enter a valid email address format (e.g., user@example.com).');
        return;
    }
    clearEmailError(fieldType);
    if (!token) {
        showEmailError(fieldType, 'Invalid session. Please refresh the page.');
        return;
    }

    const verifyBtn = document.getElementById('btn_verify_' + fieldType);
    const originalText = verifyBtn.textContent;
    verifyBtn.disabled = true;
    verifyBtn.textContent = 'Sending...';

    fetch('/cif/send_email_otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
            'email_address': emailAddress,
            'field_type': fieldType,
            'token': token
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            showSuccessMessage(fieldType, 'Verification code sent successfully to your email!');
            const otpSec = document.getElementById(fieldType + '_otp_section');
            if (otpSec) otpSec.style.display = 'block';
            verifyBtn.style.display = 'none';
            startEmailResendCountdown(fieldType, 120); // 2 minutes
        } else {
            showEmailError(fieldType, 'Error: ' + (data.message || 'Failed to send'));
            verifyBtn.disabled = false;
            verifyBtn.textContent = originalText;
        }
    })
    .catch(error => {
        showEmailError(fieldType, 'Network error. Please try again.');
        verifyBtn.disabled = false;
        verifyBtn.textContent = originalText;
    });
}

// Verify Email OTP function (ACTIVE)
function verifyEmailOTP(fieldType) {
    const otpInput = document.getElementById(fieldType + '_otp_code');
    const otpCode = otpInput ? otpInput.value.trim() : '';
    const token = getAccessToken();

    if (!otpCode) {
        showOTPError(fieldType, 'Please enter the verification code.');
        return;
    }
    if (!token) {
        showOTPError(fieldType, 'Invalid session. Please refresh the page.');
        return;
    }
    clearOTPError(fieldType);

    fetch('/cif/verify_email_otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
            'otp_code': otpCode,
            'field_type': fieldType,
            'token': token
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            showSuccessMessage(fieldType, 'Email address verified successfully!');
            const otpSec = document.getElementById(fieldType + '_otp_section');
            if (otpSec) otpSec.style.display = 'none';
            const verified = document.getElementById(fieldType + '_verified');
            if (verified) verified.style.display = 'block';
        } else {
            showOTPError(fieldType, data.message || 'Invalid verification code. Please try again.');
        }
    })
    .catch(() => {
        showOTPError(fieldType, 'Network error. Please try again.');
    });
}

// Resend functions: PHONE disabled, EMAIL active
/*
function resendOTP(fieldType) {
    // ...existing code...
}
function startResendCountdown(fieldType, seconds) {
    // ...existing code...
}
*/

function resendEmailOTP(fieldType) {
    const token = getAccessToken();
    const emailInput = document.getElementById(fieldType);
    const emailAddress = emailInput.value.trim();
    if (!token) {
        showOTPError(fieldType, 'Invalid session. Please refresh the page.');
        return;
    }
    if (!emailAddress || !isValidEmail(emailAddress)) {
        showOTPError(fieldType, 'Please enter a valid email address first.');
        return;
    }

    const resendBtn = document.getElementById('resend_' + fieldType);
    resendBtn.disabled = true;
    resendBtn.textContent = 'Sending...';

    fetch('/cif/resend_email_otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
            'field_type': fieldType,
            'email_address': emailAddress,
            'token': token
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            showSuccessMessage(fieldType, 'New verification code sent to your email!');
            startEmailResendCountdown(fieldType, 120);
            const otpInput = document.getElementById(fieldType + '_otp_code');
            if (otpInput) otpInput.value = '';
        } else {
            showOTPError(fieldType, data.message || 'Failed to resend verification code.');
            if (data.cooldown_remaining) {
                startEmailResendCountdown(fieldType, data.cooldown_remaining);
            } else {
                resendBtn.disabled = false;
                resendBtn.textContent = 'Resend Code';
                resendBtn.style.color = '#007bff';
                resendBtn.style.fontWeight = 'bold';
            }
        }
    })
    .catch(() => {
        showOTPError(fieldType, 'Network error. Please try again.');
        resendBtn.disabled = false;
        resendBtn.textContent = 'Resend Code';
        resendBtn.style.color = '#007bff';
        resendBtn.style.fontWeight = 'bold';
    });
}

function startEmailResendCountdown(fieldType, seconds) {
    const resendBtn = document.getElementById('resend_' + fieldType);
    const timerElement = document.getElementById('resend_' + fieldType + '_timer');

    resendBtn.style.display = 'none';
    timerElement.style.display = 'inline';
    timerElement.style.fontWeight = 'bold';
    timerElement.style.color = '#007bff';

    let remaining = seconds;
    const countdown = setInterval(() => {
        const minutes = Math.floor(remaining / 60);
        const secs = remaining % 60;
        timerElement.textContent = 'Resend available in ' + minutes + ':' + secs.toString().padStart(2, '0');
        if (remaining <= 0) {
            clearInterval(countdown);
            timerElement.textContent = '';
            timerElement.style.display = 'none';
            resendBtn.style.display = 'inline';
            resendBtn.disabled = false;
            resendBtn.textContent = 'Resend Code';
            resendBtn.style.fontWeight = 'bold';
            resendBtn.style.fontSize = (parseInt(window.getComputedStyle(resendBtn).fontSize) + 1) + 'px';
            resendBtn.style.color = '#007bff';
        }
        remaining--;
    }, 1000);
}

// ============================================
// NEW EMAIL OTP FUNCTIONS (for Change Mode)
// ============================================

// Show verify button when new email is entered AND different from current email
document.addEventListener('DOMContentLoaded', function() {
    const newEmailInput = document.getElementById('new_email');
    const currentEmailInput = document.getElementById('email_current');

    if (newEmailInput) {
        newEmailInput.addEventListener('input', function() {
            const verifyBtn = document.getElementById('btn_verify_new_email');
            const newEmailValue = this.value.trim().toLowerCase();
            const currentEmailValue = currentEmailInput ? currentEmailInput.value.trim().toLowerCase() : '';

            // Debug logging
            console.log('Email Verification Check:');
            console.log('  Current Email:', currentEmailValue);
            console.log('  New Email:', newEmailValue);
            console.log('  Are Different?', newEmailValue !== currentEmailValue);

            // Show verify button only if:
            // 1. New email is not empty
            // 2. New email is different from current email
            if (newEmailValue && newEmailValue !== currentEmailValue) {
                console.log('  → Showing Verify button');
                verifyBtn.style.display = 'inline-block';
            } else {
                console.log('  → Hiding Verify button');
                verifyBtn.style.display = 'none';
                document.getElementById('new_email_otp_section').style.display = 'none';
                document.getElementById('new_email_verified').style.display = 'none';
            }
        });
    }
});

function sendNewEmailOTP() {
    const emailInput = document.getElementById('new_email');
    const newEmail = emailInput.value.trim();
    const changeToken = document.querySelector('input[name="change_token"]').value;

    if (!newEmail) {
        alert('Please enter a new email address first.');
        return;
    }

    if (!isValidEmail(newEmail)) {
        alert('Please enter a valid email address format.');
        return;
    }

    if (!changeToken) {
        alert('Invalid session. Please refresh the page.');
        return;
    }

    const verifyBtn = document.getElementById('btn_verify_new_email');
    const originalText = verifyBtn.textContent;
    verifyBtn.disabled = true;
    verifyBtn.textContent = 'Sending...';

    fetch('/cif/change/send-new-email-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            'jsonrpc': '2.0',
            'method': 'call',
            'params': { 'token': changeToken, 'new_email': newEmail }
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.result && data.result.success) {
            alert('Verification code sent to ' + newEmail);
            document.getElementById('new_email_otp_section').style.display = 'block';
            verifyBtn.style.display = 'none';
            startNewEmailResendCountdown(120);
        } else {
            alert('Error: ' + (data.result ? data.result.message : 'Failed to send code'));
            verifyBtn.disabled = false;
            verifyBtn.textContent = originalText;
        }
    })
    .catch(error => {
        alert('Network error. Please try again.');
        verifyBtn.disabled = false;
        verifyBtn.textContent = originalText;
    });
}

function verifyNewEmailOTP() {
    const otpInput = document.getElementById('new_email_otp_code');
    const otpCode = otpInput.value.trim();
    const changeToken = document.querySelector('input[name="change_token"]').value;

    if (!otpCode) {
        alert('Please enter the verification code.');
        return;
    }

    if (!changeToken) {
        alert('Invalid session. Please refresh the page.');
        return;
    }

    fetch('/cif/change/verify-new-email-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            'jsonrpc': '2.0',
            'method': 'call',
            'params': { 'token': changeToken, 'otp_code': otpCode }
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.result && data.result.success) {
            alert('New email verified successfully!');
            document.getElementById('new_email_otp_section').style.display = 'none';
            document.getElementById('new_email_verified').style.display = 'block';
            document.getElementById('new_email').readOnly = true;
        } else {
            alert(data.result ? data.result.message : 'Invalid verification code.');
        }
    })
    .catch(error => {
        alert('Network error. Please try again.');
    });
}

function resendNewEmailOTP() {
    const changeToken = document.querySelector('input[name="change_token"]').value;
    if (!changeToken) {
        alert('Invalid session. Please refresh the page.');
        return;
    }

    const resendBtn = document.getElementById('resend_new_email');
    resendBtn.disabled = true;
    resendBtn.textContent = 'Sending...';

    fetch('/cif/change/resend-new-email-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            'jsonrpc': '2.0',
            'method': 'call',
            'params': { 'token': changeToken }
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.result && data.result.success) {
            alert('New verification code sent!');
            startNewEmailResendCountdown(120);
        } else {
            alert('Error: ' + (data.result ? data.result.message : 'Failed to resend'));
            if (data.result && data.result.cooldown_remaining) {
                startNewEmailResendCountdown(data.result.cooldown_remaining);
            } else {
                resendBtn.disabled = false;
                resendBtn.textContent = 'Resend Code';
            }
        }
    })
    .catch(error => {
        alert('Network error. Please try again.');
        resendBtn.disabled = false;
        resendBtn.textContent = 'Resend Code';
    });
}

function startNewEmailResendCountdown(seconds) {
    const resendBtn = document.getElementById('resend_new_email');
    const timerElement = document.getElementById('resend_new_email_timer');

    resendBtn.style.display = 'none';

    const countdown = setInterval(() => {
        const minutes = Math.floor(seconds / 60);
        const remainingSeconds = seconds % 60;
        timerElement.textContent = 'Resend available in ' + minutes + ':' + remainingSeconds.toString().padStart(2, '0');

        if (seconds <= 0) {
            clearInterval(countdown);
            timerElement.textContent = '';
            resendBtn.style.display = 'inline';
            resendBtn.disabled = false;
            resendBtn.textContent = 'Resend Code';
        }
        seconds--;
    }, 1000);
}

// Email validation helpers (ACTIVE)
function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}
function showEmailError(fieldType, message) {
    clearEmailError(fieldType);
    const errorDiv = document.createElement('div');
    errorDiv.id = fieldType + '_email_error';
    errorDiv.className = 'text-danger mt-1';
    errorDiv.style.fontSize = '12px';
    const icon = document.createElement('i');
    icon.className = 'fa fa-exclamation-triangle';
    errorDiv.appendChild(icon);
    errorDiv.appendChild(document.createTextNode(' ' + message));
    const inputGroup = document.getElementById(fieldType).closest('.input-group');
    if (inputGroup) inputGroup.parentNode.insertBefore(errorDiv, inputGroup.nextSibling);
}
function clearEmailError(fieldType) {
    const el = document.getElementById(fieldType + '_email_error');
    if (el) el.remove();
}
function showSuccessMessage(fieldType, message) {
    clearSuccessMessage(fieldType);
    const successDiv = document.createElement('div');
    successDiv.id = fieldType + '_success_message';
    successDiv.className = 'text-success mt-1';
    successDiv.style.fontSize = '12px';
    const icon = document.createElement('i');
    icon.className = 'fa fa-check-circle';
    successDiv.appendChild(icon);
    successDiv.appendChild(document.createTextNode(' ' + message));
    const inputGroup = document.getElementById(fieldType).closest('.input-group');
    if (inputGroup) inputGroup.parentNode.insertBefore(successDiv, inputGroup.nextSibling);
    setTimeout(() => { clearSuccessMessage(fieldType); }, 5000);
}
function clearSuccessMessage(fieldType) {
    const el = document.getElementById(fieldType + '_success_message');
    if (el) el.remove();
}
function showOTPError(fieldType, message) {
    clearOTPError(fieldType);
    const errorDiv = document.createElement('div');
    errorDiv.id = fieldType + '_otp_error';
    errorDiv.className = 'text-danger mt-1';
    errorDiv.style.fontSize = '12px';
    const icon = document.createElement('i');
    icon.className = 'fa fa-exclamation-triangle';
    errorDiv.appendChild(icon);
    errorDiv.appendChild(document.createTextNode(' ' + message));
    const otpSection = document.getElementById(fieldType + '_otp_section');
    if (otpSection) otpSection.parentNode.insertBefore(errorDiv, otpSection.nextSibling);
}
function clearOTPError(fieldType) {
    const el = document.getElementById(fieldType + '_otp_error');
    if (el) el.remove();
}

// Real-time field validation
document.addEventListener('DOMContentLoaded', function() {
    // Add event listeners for field changes
    ['mobile', 'phone', 'email', 'email_address'].forEach(fieldType => {
        const input = document.getElementById(fieldType);
        if (input) {
            input.addEventListener('input', function() {
                // Clear email error when user starts typing
                if (fieldType === 'email' || fieldType === 'email_address') {
                    clearEmailError(fieldType);
                }

                // Clear success messages when user changes field value
                clearSuccessMessage(fieldType);

                // Delay check slightly to allow user to finish typing
                setTimeout(() => {
                    checkVerificationStatus();
                }, 500);
            });
        }

        // Add event listener for OTP input fields
        const otpInput = document.getElementById(fieldType + '_otp_code');
        if (otpInput) {
            otpInput.addEventListener('input', function() {
                // Clear OTP errors when user starts typing in OTP field
                clearOTPError(fieldType);
            });
        }
    });
});

// Validate shareholder percentage before form submission
(function() {
    var shareholderInput = document.getElementById('shareholder_percentage');
    var shareholderErrorDiv = document.getElementById('shareholder_percentage_error');
    var submitButton = document.getElementById('submit_cif_company_form');
    var form = document.querySelector('form[method="POST"]');

    if (shareholderInput && form) {
        var requiredValue = parseFloat(shareholderInput.getAttribute('data-required-percentage'));
        // Fallback: try to read from visible span if attribute missing or not numeric
        if (isNaN(requiredValue)) {
            var span = document.getElementById('required_percentage_display');
            if (span) {
                // trim and remove non-numeric characters (like %)
                var txt = (span.textContent || span.innerText || '').trim().replace('%','');
                requiredValue = parseFloat(txt);
            }
        }
        var requiredValueDisplay = isNaN(requiredValue) ? null : (Math.abs(requiredValue - Math.round(requiredValue)) < 0.0001 ? String(Math.round(requiredValue)) : String(requiredValue));

        // Function to validate percentage
        function validateShareholderPercentage() {
            var enteredValue = parseFloat(shareholderInput.value);

            if (isNaN(enteredValue)) {
                shareholderErrorDiv.innerHTML = 'Please enter a valid percentage value.';
                shareholderErrorDiv.classList.remove('d-none');
                shareholderInput.classList.add('is-invalid');
                return false;
            }

            // If a required remaining percentage is defined, ensure entered remaining







            // Otherwise it's fine
            shareholderErrorDiv.classList.add('d-none');
            shareholderInput.classList.remove('is-invalid');
            return true;
        }

        // Real-time validation as user types
        shareholderInput.addEventListener('input', function() {
            var enteredValue = parseFloat(this.value);

            if (!isNaN(enteredValue)) {
                if (!isNaN(requiredValue) && enteredValue > requiredValue) {
                     var reqText = requiredValueDisplay + '%';
                     shareholderErrorDiv.innerHTML = 'Maximum allowed: ' + reqText + '. You entered ' + enteredValue + '%.';
                     shareholderErrorDiv.classList.remove('d-none');
                     shareholderInput.classList.add('is-invalid');
                     if (submitButton) submitButton.disabled = true;
                } else {
                    shareholderErrorDiv.classList.add('d-none');
                    shareholderInput.classList.remove('is-invalid');
                    if (submitButton) submitButton.disabled = false;
                }
            } else {
                // if cleared, hide error
                shareholderErrorDiv.classList.add('d-none');
                shareholderInput.classList.remove('is-invalid');
                if (submitButton) submitButton.disabled = false;
            }
        });

        // Validate on form submission (most reliable method)
        form.addEventListener('submit', function(e) {
            if (!validateShareholderPercentage()) {
                e.preventDefault();
                e.stopPropagation();
                shareholderInput.focus();
                window.scrollTo({top: shareholderInput.offsetTop - 200, behavior: 'smooth'});
                return false;
            }
        });

        // Validate on button click as backup
        if (submitButton) {
            submitButton.addEventListener('click', function(e) {
                if (!validateShareholderPercentage()) {
                    e.preventDefault();
                    e.stopPropagation();
                    shareholderInput.focus();
                    window.scrollTo({top: shareholderInput.offsetTop - 200, behavior: 'smooth'});
                    return false;
                }
            });
        }
    }
})();
